const DE = {
 "id": "pro192-4-2-late-fees",
 "title": "Late fees without instanceof",
 "src": "src",
 "extra": [
  "cham"
 ],
 "main": "KiemTra",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [
  {
   "id": "R1",
   "en": "no instanceof / getClass() in the computation — polymorphism decides",
   "vi": "không instanceof / getClass() trong phần tính — đa hình tự quyết",
