  {
   "name": "one of each, all late",
   "input": "BOOK;Clean Code;20\nMAG;Tech Weekly;12\nDVD;The Matrix;8\n",
   "expected": "Clean Code | loan 14 days | kept 20 | fee 12000\nTech Weekly | loan 7 days | kept 12 | fee 5000\nThe Matrix | loan 3 days | kept 8 | fee 35000\nTotal: 52000\n"
  },
  {
   "name": "on time and exactly on the last day",
   "input": "BOOK;Refactoring;14\nMAG;Java Magazine;7\nDVD;Inception;3\nDVD;Up;4\n",
   "expected": "Refactoring | loan 14 days | kept 14 | fee 0\nJava Magazine | loan 7 days | kept 7 | fee 0\nInception | loan 3 days | kept 3 | fee 0\nUp | loan 3 days | kept 4 | fee 5000\nTotal: 5000\n"
  },
